create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.WBS_ART_AKTION_PER (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Filiale-ID (6906, 3000, ...).',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Nebenbetrieb-ID (Lager, Filiale, ...).',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer.',
	AKTION_ID VARCHAR(10) NOT NULL COMMENT 'Aktionsnummer.',
	KJWO_VON NUMBER(38,0) NOT NULL COMMENT 'Start-Kalenderwoche der Aktion, entsprechend dat_von.',
	DAT_VON DATE NOT NULL COMMENT 'Aktion gültig von: Datum im Format JJJJ-MM-TT.',
	DAT_BIS DATE NOT NULL COMMENT 'Aktion gültig bis: Datum im Format JJJJ-MM-TT.',
	AKTION_DAUER NUMBER(38,0) NOT NULL COMMENT 'Dauer der Aktion.',
	WTAG_ID_VON NUMBER(38,0) NOT NULL COMMENT 'Wochentag des Werbestarts.',
	MUTTER_WB_ID NUMBER(38,0) COMMENT 'Artikelnummer des Werbemutterartikels.',
	MENGE_SA_BME NUMBER(38,3) COMMENT 'Tatsächlich verkaufte Promotion Menge in der historischen Aktion in BME (wurde gefiltert auf bewart = 1002, SonderAktion, beinhaltet auch BBY),',
	ZEITRAUM_KORRIGIERTE_MENGE NUMBER(38,3) COMMENT 'Korrigierte Menge in BME.',
	ZEITRAUM_MENGE_AF_4WO NUMBER(38,3) COMMENT 'Menge Abverkauf AF 4 Wochen vor Aktion.',
	SALES_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob in einer Woche Absätze vorhanden waren.',
	IN_GRUPPE_FG NUMBER(38,0) COMMENT 'Flag: Gibt an, ob ein Artikel Teil einer Serie war.',
	ANZ_ART_IN_GRUPPE NUMBER(38,0) COMMENT 'Gibt die Anzahl der Artikel in einer Serie der aktuellen Aktion an.',
	TV_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel TV-Werbung hatte.',
	TITELSEITE_FG NUMBER(38,0) COMMENT 'Flag: Gibt an, ob der Artikel auf der Titelseite der Werbung abgebildet war.',
	RUECKSEITE_FG NUMBER(38,0) COMMENT 'Flag: Gibt an, ob der Artikel auf der Rückseite der Werbung abgebildet war.',
	GK_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob der Artikel eine Gondelkopfplatzierung hatte.',
	VK_AKTION_BRUTTO NUMBER(38,2) COMMENT 'VK-Preis Aktion Brutto.',
	VK_VOR_AKTION_BRUTTO NUMBER(38,2) COMMENT 'VK-Preis vor Aktion Brutto.',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	MULTI_OFFER_ID_FG NUMBER(38,0) COMMENT 'Flag zur Markierung von Aktionszeiträumen mit multiplen Angeboten. Im selben Zeitraum können für einen Artikel mehrere Angebote existieren, z.B. über den Prospekt und über die K-Card.',
	BONUSKAUF_FG NUMBER(38,0) COMMENT 'Flag zur Markierung von Bonusbuy-Aktionen. Zuordnung von BONUSKAUF_ID und AKTION_ID steht in L_BONUSKAUF.',
	LOKALE_GESCHAEFTSVORFALL_BEZ VARCHAR(40) COMMENT 'Bezeichnung des Bonusbuy-Geschäftsvorfalls in lokaler Sprache. Zuordnung von BONUSKAUF_ID und GESCHAEFTSVORFALL_ID steht in L_BONUSKAUF.',
	MANDANT_ID_VZ NUMBER(38,0) COMMENT 'Mandant VZ. Das Auslieferungsland kann sich in gewissen Fällen vom Markt unterscheiden, z.B. wird Moldau (mandant_id 4) aus Rumänien (mandant_id 7) beliefert. Das Attribut wird hier redundant angelegt um die Performance im Frontend zu steigern (es wird ein Join mit WBS_WERBEAENDERUNGEN vermieden).',
	WUP_ID_VZ NUMBER(38,0) COMMENT 'WUP ID VZ. Marktnummer des Verteilzentrums. Das Attribut wird hier redundant angelegt um die Performance im Frontend zu steigern.',
	BERECHNETE_MENGE_GESAMT_BME NUMBER(38,3) COMMENT 'Gibt die urspruenglich berechnete Werbemenge fuer diese Artikel-Markt-Aktion-Kombination aus.',
	LIEF_MENGE_INITIAL_BME NUMBER(38,3) COMMENT 'Liefermenge, die für die Erstlieferung versendet wurde, in BME. Gibt die tatsaechlich gelieferte Menge in der initialen Belieferung an (nach Fair Share).',
	LIEF_MENGE_HOCHRECHNUNG_BME NUMBER(38,3) COMMENT 'Liefermenge, die nach der Anpassungsberechnung versendet wurde, in BME. Gibt die tatsaechlich gelieferte Menge aus der Hochrechnung an (nach Fair Share). WBS führt eine Berechnung nach der Initialen Belieferung durch (Hochrechnung), was dann die nachgelieferte Menge in der betrachteten Spalte beinflusst (kann auch 0 sein). Die Summe von lief_menge_initial_bme_ref und lief_menge_hochrechnung_bme_ref kann sich unterscheiden von berechnete_menge_gesamt_bme_ref.',
	LIEF_MENGE_ANTEIL_PROZENT NUMBER(38,2) COMMENT 'Gibt an, wieviel % der Werbeware im Vergleich zur urspruenglich berechneten Werbemenge ausgeliefert wurde. Dies dient dem User dazu zu bewerten, ob der Werbeabsatz eventuell zu gering war, weil Ware nicht im Markt vorhanden war.\n            \""(MENGE_INITIAL_BME + MENGE_WBS [nach Umrechnung von AME zu BME]) / MENGE_GESAMT_BME\""',
	NUR_ONLINE_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob die Werbung nur online geschaltet wurde.',
	KUNDENKARTE_PERSONALISIERT_FG NUMBER(38,0) COMMENT 'Flag: Zeigt an, ob die Werbung ein personalisierter Kundenkarten-Coupon ist.',
	STILLE_AKTION_FG NUMBER(38,0) COMMENT 'Flag: Stille Aktion Typ: \""In Store Promotions\"" (ohne Mengenberechnung) - Identifikation, um Artikel mit dieser FG aus der Berechnung auszuschließen.\n            Stille Aktionen sind Werbungen, die nur in Geschäften zu sehen sind und nirgendwo beworben wurden, und können je nach Typ eine Mengenberechnung haben oder nicht. Der Typ wird im Voraus von einem User vergeben. Für diesen Typ Stille Aktion werden keine Mengenberechnungen durchgeführt.',
	STILLE_AKTION_MIT_MENGE_FG NUMBER(38,0) COMMENT 'Flag: Stille Aktion Typ: \""In Store Promotions mit Menge\"" - für Kombination WERBEMITTEL_ART_ID = 0920 & WERBEMITTEL_ID = 50. Artikel wird nur in Filiale beworben, erhält aber Mengenberechnung.\n            Stille Aktionen sind Werbungen, die nur in Geschäften zu sehen sind und nirgendwo beworben wurden, und können je nach Typ eine Mengenberechnung haben oder nicht. Der Typ wird im Voraus von einem User vergeben. Für diesen Typ Stille Aktion werden Mengenberechnungen durchgeführt.',
	WERBEFLAECHE_ABSCHNITT_NAME VARCHAR(100) COMMENT 'Gibt an, in welchem Abschnitt eines Bereichs (in einer Werbeflyerseite) das Angebot abgebildet ist (z.B. TOPLEFT1) - Section (of leaflet page) where the advertisement is put.',
	WERBEFLAECHE_THEMA_BEZ VARCHAR(100) COMMENT 'Bezeichnung für die WERBEFLAECHE_THEMA_ID (z.B. PANO01 = Schulanfang) - Name of the promotion theme.',
	MENGE_GESAMT_BME NUMBER(38,3) COMMENT 'Die Summe der gesamten Promotionsmenge, die während des Aktionszeitraums verkauft wurde, unabhängig davon, ob sie durch die Promotion oder aus anderen Gründen, z.B. Kundenkartenrabatt verkauft wurde, in BME (für bewart = Sonderaktion und aktionsfrei, z.B. Kundenkarte, Bonusrabatt, etc.).',
	FIXMENGE_FG NUMBER(38,0) COMMENT 'Fixmenge EK Flag gibt an, ob vom Einkauf eine Fixmenge für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	FIXMENGE_WFL_FG NUMBER(38,0) COMMENT 'Fixmenge WFL Flag gibt an, ob vom Warenfluss eine Fixmenge für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	MINDESTPLATZIERUNG_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob vom Warenfluss eine Mindestplatzierung für diese Aktion festgelegt wurde. Aus dbp_data.wbs_werbeaenderungen.',
	constraint PK_WBS_ART_AKTION_PER primary key (MANDANT_ID, WUP_ID, NB_ID, ART_ID, AKTION_ID, DAT_VON)
)COMMENT='SCM-WBS - Operational data for WBS tool. This table contains data for the historry of articles and promotions. It is not actually a historization table that tracks changes but just the occurences of articles in promotions over time.'
;
